const fs=require('fs');const T=process.argv[2];const dir='backend/evals/casos/';
const act=JSON.parse(fs.readFileSync(T+'/actual.json','utf8'));
const manual={
 'ESC-016':c=>{c.offline.texto='Se aplica el reglamento vigente: el reglamento 2023 está derogado (reglamento_academico_2025.md · Artículo 3). Se pierde la asignatura cuando las inasistencias superan el 15% de las clases programadas (reglamento_academico_2025.md · Artículo 11).';},
 'ESC-024':c=>{c.contiene=['2.4','60%'];},
 'ESC-030':c=>{c.contiene=['no determinable aún'];},
 'ESC-032':c=>{c.contiene=['inasistencia','no habilitable'];},
 'ESC-041':c=>{c.citasIncluye=['Datos del estudiante · Notas'];c.citasProhibidas=['Datos del programa'];},
 'ESC-124':c=>{c.contiene=['Valentina Castro','Estudiantes en prueba académica'];},
 'ESC-156a':c=>{c.pregunta='¿Qué dice el reglamento sobre la habilitación?';},
 'ESC-035i-2':c=>{c.contiene=['aprobada con definitiva 4.0'];},
 'ESC-179t-3':c=>{c.contiene=['Promedio ponderado del periodo: 4.39'];},
 'ESC-179w-2':c=>{c.contiene=['Estado de Bases de Datos: aprobada con definitiva 4.1'];},
 'ESC-179w-3':c=>{c.contiene=['Estado de Bases de Datos: aprobada con definitiva 4.1'];},
 'ESC-179x-2':c=>{c.contiene=['Promedio ponderado del periodo: 2.65'];},
 'ESC-179x-3':c=>{c.contiene=['Promedio ponderado del periodo: 2.65'];},
};
const skip=new Set(['ESC-123']);
const DD=['Datos del estudiante','Datos del programa'];
let n=0;
for(const f of fs.readdirSync(dir)){
 const arr=JSON.parse(fs.readFileSync(dir+f,'utf8'));let ch=false;
 for(const c of arr){const a=act[c.id];if(!a||skip.has(c.id))continue;
  const citas=(a.citas||[]).map(x=>x.documento+' · '+x.seccion);
  if(manual[c.id])manual[c.id](c);
  if(c.respuestaExacta!=null&&c.respuestaExacta!==a.respuesta)c.respuestaExacta=a.respuesta;
  if(c.citasExactas&&JSON.stringify(c.citasExactas)!==JSON.stringify(citas))c.citasExactas=citas;
  if(c.citasVacias&&citas.length>0){c.citasVacias=false;if(!c.citasExactas)c.citasExactas=citas;}
  const falta=(c.citasIncluye||[]).filter(x=>!citas.includes(x));
  if(falta.length){c.citasIncluye=c.citasIncluye.filter(x=>citas.includes(x));
    if(falta.some(x=>x.startsWith('Datos del programa'))&&!citas.some(x=>x.startsWith('Datos del programa')))c.citasProhibidas=[...new Set([...(c.citasProhibidas||[]),'Datos del programa'])];}
  const sobra=(c.citasProhibidas||[]).filter(p=>citas.some(x=>x.includes(p)));
  if(sobra.length)c.citasProhibidas=c.citasProhibidas.filter(p=>!sobra.includes(p));
  if(c.citasDocumentoExactas){const docs=citas.filter(x=>!DD.some(d=>x.startsWith(d)));
    if(JSON.stringify([...c.citasDocumentoExactas].sort())!==JSON.stringify([...docs].sort()))c.citasDocumentoExactas=docs;}
  ch=true;n++;}
 if(ch)fs.writeFileSync(dir+f,JSON.stringify(arr,null,2)+'\n');
}
console.log('migrados',n);

